"""Evaluation helpers.

Every function takes the anomaly ``scores`` first and the ground-truth
``labels`` second, so that the labels can only ever be consumed *after*
prediction scores exist (requirement R10, paper Sec. 5.1).
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores, labels) -> float:
    """Area under the ROC curve (requirement R9)."""
    return float(roc_auc_score(np.asarray(labels), np.asarray(scores)))


def auc_pr_ap(scores, labels) -> float:
    """Average precision, the AUC-PR convention used by ADBench/PyOD (R9)."""
    return float(average_precision_score(np.asarray(labels), np.asarray(scores)))


def auc_pr_trapezoid(scores, labels) -> float:
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    precision, recall, _ = precision_recall_curve(np.asarray(labels), np.asarray(scores))
    order = np.argsort(recall)
    return float(np.trapezoid(precision[order], recall[order]))


def summarize(values) -> dict:
    """mean / std / min / max / list of the 5 repeated runs (requirement R8)."""
    v = np.asarray(values, dtype=float)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "values": [float(x) for x in v],
        "n_repeats": int(v.size),
    }

